CREATE COLUMN TABLE "TEST_AP"."WOR5" ("DocEntry" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '202', "LogInstanc" INTEGER CS_INT DEFAULT 0, "LineNum" INTEGER CS_INT NOT NULL , "RefDocEntr" INTEGER CS_INT, "RefDocNum" INTEGER CS_INT, "ExtDocNum" NVARCHAR(100), "RefObjType" NVARCHAR(20), "IssueDate" LONGDATE CS_LONGDATE, "Remark" NVARCHAR(254), PRIMARY KEY ("DocEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "WOR5_DOC_ENTRY" ON "TEST_AP"."WOR5" ( "DocEntry" ASC )